@extends('admin.layouts.app',['title'=>'Users','heading'=>'Users']) @section('content')<x-pulse.page-header title="Users" description="Manage account status, roles, and access."><x-slot:actions><a class="p-button" href="{{ route('admin.users.create') }}">Add user</a></x-slot:actions></x-pulse.page-header><x-pulse.errors/><x-pulse.card>@if($users->isEmpty())<x-pulse.empty title="No users found">Add an account to begin.</x-pulse.empty>@else<x-pulse.table><thead><tr><th scope="col">Name</th><th scope="col">Email</th><th scope="col">Status</th><th scope="col">Roles</th><th scope="col">Actions</th></tr></thead><tbody>@foreach($users as $user)<tr><td data-label="Name"><strong>{{ $user->name }}</strong></td><td data-label="Email">{{ $user->email }}</td><td data-label="Status"><x-pulse.badge :variant="$user->status === 'active' ? 'success' : 'neutral'">{{ ucfirst($user->status) }}</x-pulse.badge></td><td data-label="Roles">{{ $user->roles->pluck('label')->join(', ') ?: 'No roles' }}</td><td data-label="Actions"><div class="p-actions"><a class="p-button p-button--secondary" href="{{ route('admin.users.edit',$user) }}">Edit <span class="sr-only">{{ $user->name }}</span></a>@if(!$user->is(auth()->user()))<form method="POST" action="{{ route('admin.users.destroy',$user) }}">@csrf @method('DELETE')<x-pulse.button variant="danger" data-confirm data-confirm-title="Delete user?" data-confirm-message="This permanently deletes the account and cannot be undone.">Delete</x-pulse.button></form>@endif</div></td></tr>@endforeach</tbody></x-pulse.table><x-pulse.pagination :paginator="$users"/>@endif</x-pulse.card>@endsection
